const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
const escapeHtml=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const renderProjects=()=>{$('#projects-grid').innerHTML=projects.map((p,i)=>`<article class="project-card reveal" data-category="${p.category}"><div class="project-visual" style="--gradient:${p.gradient}"><span class="project-icon">${escapeHtml(p.icon)}</span><span class="project-number">0${i+1}</span></div><div class="project-body"><span class="project-category">${escapeHtml(p.badge)}</span><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.summary)}</p><div class="tags">${p.stack.slice(0,3).map(t=>`<span class="tag">${escapeHtml(t)}</span>`).join('')}</div><button class="detail-button" type="button" data-project="${p.id}">Lihat detail <span>＋</span></button></div></article>`).join('')};
const renderTimeline=()=>{$('#timeline').innerHTML=experiences.map((x,i)=>`<article class="timeline-item reveal"><span class="timeline-dot" aria-hidden="true"></span><button class="timeline-button" type="button" aria-expanded="${i===0}" aria-controls="experience-${i}"><div><div class="meta">${escapeHtml(x.period)}</div><h3>${escapeHtml(x.role)}</h3><p class="org">${escapeHtml(x.organization)}</p></div><span class="chevron"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></span></button><div class="timeline-content" id="experience-${i}" ${i===0?'':'hidden'}><ul>${x.highlights.map(h=>`<li>${escapeHtml(h)}</li>`).join('')}</ul></div></article>`).join('')};
const renderAchievements=()=>{$('#achievement-grid').innerHTML=achievements.map(a=>`<article class="achievement-card reveal" data-category="${a.category}"><div class="achievement-icon" style="--icon-bg:${a.colors[0]};--icon-color:${a.colors[1]}">${a.icon}</div><div><small>${escapeHtml(a.badge)}</small><h3>${escapeHtml(a.title)}</h3><p>${escapeHtml(a.description)}</p></div><span class="achievement-year">${escapeHtml(a.year)}</span></article>`).join('')};
renderProjects();renderTimeline();renderAchievements();

const storedTheme=localStorage.getItem('ardi-theme');
const initialTheme=storedTheme||'light';document.documentElement.dataset.theme=initialTheme;
const themeButton=$('#theme-toggle');
const updateThemeLabel=()=>themeButton.setAttribute('aria-label',document.documentElement.dataset.theme==='dark'?'Aktifkan mode terang':'Aktifkan mode gelap');updateThemeLabel();
themeButton.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('ardi-theme',next);updateThemeLabel()});

const menuButton=$('#menu-toggle'),mobileMenu=$('#mobile-menu');
const closeMenu=()=>{mobileMenu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Buka menu')};
menuButton.addEventListener('click',()=>{const open=mobileMenu.hidden;mobileMenu.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Tutup menu':'Buka menu')});
$$('a',mobileMenu).forEach(a=>a.addEventListener('click',closeMenu));

const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});$$('.reveal').forEach(el=>revealObserver.observe(el));
const sections=$$('main section[id]');
const spyObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){$$('.nav-links a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+entry.target.id))}}),{rootMargin:'-40% 0px -50% 0px'});sections.forEach(s=>spyObserver.observe(s));

const roles=['Data Scientist','Machine Learning Engineer','LLM Developer'];let roleIndex=0,charIndex=roles[0].length,deleting=true;
const typeRole=()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const target=$('#typing-role'),word=roles[roleIndex];charIndex+=deleting?-1:1;target.textContent=word.slice(0,charIndex);let wait=deleting?45:80;if(!deleting&&charIndex===word.length){deleting=true;wait=1600}else if(deleting&&charIndex===0){deleting=false;roleIndex=(roleIndex+1)%roles.length;wait=350}setTimeout(typeRole,wait)};setTimeout(typeRole,1200);

$('#timeline').addEventListener('click',e=>{const button=e.target.closest('.timeline-button');if(!button)return;const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));$('#'+button.getAttribute('aria-controls')).hidden=open});
const setupFilters=(containerSelector,itemSelector)=>{$(containerSelector).addEventListener('click',e=>{const button=e.target.closest('.filter');if(!button)return;$$('.filter',$(containerSelector)).forEach(b=>b.classList.toggle('active',b===button));$$(itemSelector).forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter)})};
setupFilters('#project-filters','.project-card');setupFilters('#achievement-filters','.achievement-card');

const modal=$('#project-modal'),dialog=$('.modal-dialog',modal);let lastFocus=null;
const openModal=p=>{lastFocus=document.activeElement;$('#modal-badge').textContent=p.badge;$('#modal-title').textContent=p.title;$('#modal-summary').textContent=p.summary;$('#modal-problem').textContent=p.problem;$('#modal-solution').textContent=p.solution;$('#modal-impact').textContent=p.impact;$('#modal-stack').innerHTML=p.stack.map(t=>`<span class="tag">${escapeHtml(t)}</span>`).join('');modal.hidden=false;modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';requestAnimationFrame(()=>dialog.focus())};
const closeModal=()=>{modal.hidden=true;modal.setAttribute('aria-hidden','true');document.body.style.overflow='';if(lastFocus)lastFocus.focus()};
$('#projects-grid').addEventListener('click',e=>{const button=e.target.closest('[data-project]');if(button)openModal(projects.find(p=>p.id===button.dataset.project))});$$('[data-close-modal]').forEach(el=>el.addEventListener('click',closeModal));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)closeModal();if(e.key==='Tab'&&!modal.hidden){const focusable=$$('button,a,input,textarea,[tabindex]:not([tabindex="-1"])',dialog).filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});

let toastTimer;const showToast=message=>{const toast=$('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3500)};
$('#contact-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;let valid=true;$$('.field',form).forEach(field=>{const input=$('input,textarea',field),error=$('.error',field);error.textContent='';input.removeAttribute('aria-invalid');if(!input.checkValidity()){valid=false;input.setAttribute('aria-invalid','true');error.textContent=input.validity.typeMismatch?'Masukkan alamat email yang valid.':input.validity.tooShort?'Pesan minimal 10 karakter.':'Bagian ini perlu diisi.'}});if(!valid){showToast('Mohon periksa kembali data yang Anda isi.');return}const data=new FormData(form);const subject=encodeURIComponent(`Diskusi dengan ${data.get('name')}`),body=encodeURIComponent(`Nama: ${data.get('name')}\nEmail: ${data.get('email')}\n\n${data.get('message')}\n\nDikirim dari website portofolio.`);window.location.href=`mailto:?subject=${subject}&body=${body}`;showToast('Draf pesan telah disiapkan di aplikasi email Anda.')});
$('#year').textContent=new Date().getFullYear();
